const S011_QWEN_SLOT_SCRIPT_BASE64 = '';

const sourceInput = $('When Executed by Another Workflow').first().json || {};
const promptSettings = $input.first().json || {};
const constants = promptSettings.constants || {};
const modelRun = normalizeText(constants.model?.Model_Run);
const baseUrlRun = normalizeText(constants.BaseUrl?.BaseUrl_Run);
const apiKeyRun = normalizeText(constants.Authorization?.APIKey_Run);

function normalizeText(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

if (!modelRun) throw new Error('缺少 constants.model.Model_Run，无法构造模型请求');
if (!baseUrlRun) throw new Error('缺少 constants.BaseUrl.BaseUrl_Run，无法构造模型请求');
if (!apiKeyRun) throw new Error('缺少 constants.Authorization.APIKey_Run，无法构造模型请求');

function normalizeRatio(value) {
  const fullwidthColon = String.fromCharCode(0xFF1A);
  return normalizeText(value)
    .replace(new RegExp(fullwidthColon, 'g'), ':')
    .replace(/\s+/g, '');
}

const targetPlatform = normalizeText(sourceInput.targetPlatform).toUpperCase();
const ratio = normalizeRatio(sourceInput.ratio);
const platformRule = targetPlatform.includes('OZON')
  ? normalizeText(promptSettings.ozonPlatformRule)
  : normalizeText(promptSettings.wbPlatformRule);

const requiredFields = ['productName', 'productAppearance', 'scenePrompt', 'ratio'];
const missing = requiredFields.filter((key) => !normalizeText(sourceInput[key]));
if (missing.length) {
  throw new Error('Missing required input field(s): ' + missing.join(', '));
}

