  jobDescription: normalizeText(sourceInput.jobDescription),
  productName: normalizeText(sourceInput.productName),
  productAppearance: normalizeText(sourceInput.productAppearance),
  Country: normalizeText(sourceInput.Country),
  targetPlatform: normalizeText(sourceInput.targetPlatform),
  styleDirection: normalizeText(sourceInput.styleDirection),
  targetMarket: normalizeText(sourceInput.targetMarket),
  platformRule,
  scenePrompt: normalizeText(sourceInput.scenePrompt),
  title: normalizeText(sourceInput.title),
  titleDescription: normalizeText(sourceInput.titleDescription),
  viewImageAdd1: normalizeText(sourceInput.viewImageAdd1),
  viewImageAdd2: normalizeText(sourceInput.viewImageAdd2),
  viewImageAdd3: normalizeText(sourceInput.viewImageAdd3),
  ratio,
};

