const response = $input.first().json || {};
const sourceInput = $('When Executed by Another Workflow').first().json || {};

function normalizeText(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function normalizeRatio(value) {
  return normalizeText(value).replace(/：/g, ':').replace(/\s+/g, '');
}

function parseModelContent(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }
  if (typeof value !== 'string') {
    throw new Error('Qwen response did not include JSON content at choices[0].message.content.');
  }

  let text = value.trim();
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) {
    text = fenced[1].trim();
  }

  try {
    return JSON.parse(text);
  } catch (firstError) {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start !== -1 && end > start) {
      return JSON.parse(text.slice(start, end + 1));
    }
    throw firstError;
  }
}

const modelContent = response?.choices?.[0]?.message?.content ?? response?.message?.content ?? response?.content;
let parsed;
try {
  parsed = parseModelContent(modelContent);
} catch (error) {
  const preview = typeof modelContent === 'string' ? modelContent.slice(0, 500) : JSON.stringify(modelContent).slice(0, 500);
  throw new Error(`Qwen output is not valid JSON: ${error.message}. Output preview: ${preview}`);
}

const prompt = normalizeText(parsed.prompt || parsed.positivePrompt || parsed['正向提示词']);
const negativePrompt = normalizeText(parsed.negativePrompt || parsed.negative_prompt || parsed['反向提示词']);
const ratio = normalizeRatio(sourceInput.ratio || parsed.ratio || parsed['生图比例']);
const productName = normalizeText(sourceInput.productName);
const taskIndexValue = Number(sourceInput.taskIndex);
const taskIndex = Number.isInteger(taskIndexValue) && taskIndexValue > 0 ? taskIndexValue : null;
const sceneIndexValue = Number(sourceInput.sceneIndex);
const sceneIndex = Number.isInteger(sceneIndexValue) && sceneIndexValue > 0 ? sceneIndexValue : taskIndex;
const sceneKey = normalizeText(sourceInput.sceneKey);

const missing = [];
if (!productName) missing.push('productName');
if (!prompt) missing.push('prompt');
if (!ratio) missing.push('ratio');
if (missing.length) {
  throw new Error(`Missing required output field(s): ${missing.join(', ')}`);
}

return [{
  json: {
    productName,
    prompt,
    negativePrompt,
    ratio,
    taskIndex,
    sceneIndex,
    sceneKey,
  },
}];

const fs = require('fs');
const path = require('path');
const SEMAPHORE_NAMESPACE = "n8n-e003-s011-qwen-semaphore-v1";

function readLease() {
  const raw = String($('Acquire S011 Qwen Slot').first().json?.stdout || '').trim();
  let lease;
  try {
    lease = JSON.parse(raw);
  } catch (error) {
    throw new Error('Invalid S011 semaphore lease JSON: ' + error.message);
  }

  const slotIndex = Number(lease.slotIndex);
  const ownerToken = String(lease.ownerToken || '');
  if (lease.namespace !== SEMAPHORE_NAMESPACE) throw new Error('Unexpected S011 semaphore namespace.');
  if (!Number.isInteger(slotIndex) || slotIndex < 1 || slotIndex > 2) throw new Error('Invalid S011 semaphore slotIndex.');
  if (!/^[A-Za-z0-9_-]{24}$/.test(ownerToken)) throw new Error('Invalid S011 semaphore ownerToken.');

  const root = Buffer.from(String(lease.rootBase64 || ''), 'base64').toString('utf8');
  if (!root || path.basename(root) !== SEMAPHORE_NAMESPACE) throw new Error('Invalid S011 semaphore root.');
  const rootStat = fs.lstatSync(root);
  if (!rootStat.isDirectory() || rootStat.isSymbolicLink()) throw new Error('Unsafe S011 semaphore root.');

  const slotPath = path.join(root, 'slot-' + slotIndex);
  if (path.dirname(path.resolve(slotPath)) !== path.resolve(root)) throw new Error('Unsafe S011 semaphore slot path.');
  return { root, slotPath, slotIndex, ownerToken };
}

function releaseLease(lease) {
  const slotStat = fs.lstatSync(lease.slotPath);
  if (!slotStat.isDirectory() || slotStat.isSymbolicLink()) throw new Error('Unsafe S011 semaphore slot.');

  const ownerPath = path.join(lease.slotPath, 'owner.json');
  const ownerStat = fs.lstatSync(ownerPath);
  if (!ownerStat.isFile() || ownerStat.isSymbolicLink()) throw new Error('Unsafe S011 semaphore owner metadata.');
  const owner = JSON.parse(fs.readFileSync(ownerPath, 'utf8'));
  if (owner.ownerToken !== lease.ownerToken) throw new Error('S011 semaphore owner mismatch; slot was not released.');

  const tombstone = path.join(
    lease.root,
    '.release-' + lease.slotIndex + '-' + lease.ownerToken + '-' + Date.now()
  );
  fs.renameSync(lease.slotPath, tombstone);
  fs.unlinkSync(path.join(tombstone, 'owner.json'));
  fs.rmdirSync(tombstone);
}

const responseItems = $input.all();
releaseLease(readLease());
return responseItems;

