function describeError(value) {
  if (typeof value === 'string') return value.trim();
  if (value && typeof value === 'object') {
    return String(value.message || value.description || JSON.stringify(value)).trim();
  }
  return String(value || '').trim();
}

const taskIndex = Number.isInteger(Number(sourceInput.taskIndex)) ? Number(sourceInput.taskIndex) : 'unknown';
const sceneKey = String(sourceInput.sceneKey || '').trim() || 'unknown';
const upstreamMessage = describeError(errorItem.error || errorItem.message || errorItem.description)
  || 'Unknown HTTP request error';
const cleanupSuffix = releaseError ? ' Semaphore release warning: ' + releaseError : '';
throw new Error(
  'S011 Qwen request failed after 3 attempts (taskIndex=' + taskIndex +
